/**
 * Splits an array into consecutive groups of a specified size.
 * 
 * @param {Array} items - The array to chunk.
 * @param {number} size - The size of each chunk.
 * @returns {Array} A new array of chunks.
 */
export function chunk(items, size) {
  if (!Array.isArray(items)) {
    throw new TypeError('Input must be an array.');
  }

  if (
    typeof size !== 'number' ||
    !Number.isInteger(size) ||
    size < 1 ||
    !Number.isFinite(size)
  ) {
    throw new RangeError('Size must be an integer of at least 1.');
  }

  const result = [];
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }
  return result;
}

/**
 * Flattens an array up to a specified depth.
 * 
 * @param {Array} items - The array to flatten.
 * @param {number} [depth=1] - The depth level to flatten.
 * @returns {Array} A new flattened array.
 */
export function flatten(items, depth = 1) {
  if (!Array.isArray(items)) {
    throw new TypeError('Input must be an array.');
  }

  if (
    depth !== Infinity &&
    (typeof depth !== 'number' ||
      !Number.isInteger(depth) ||
      depth < 0 ||
      Number.isNaN(depth))
  ) {
    throw new RangeError('Depth must be a non-negative integer or Infinity.');
  }

  function flattenRecursive(arr, currentDepth) {
    let result = [];

    for (const item of arr) {
      if (currentDepth > 0 && Array.isArray(item)) {
        result.push(...flattenRecursive(item, currentDepth - 1));
      } else {
        result.push(item);
      }
    }

    return result;
  }

  return flattenRecursive(items, depth);
}
