/**
 * Converts text to title case according to specific rules.
 * @param {string} text
 * @returns {string}
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') return '';

  const smallWords = new Set([
    'a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as'
  ]);

  const isAcronym = (word) => /^[A-Z]{2,}$/.test(word);

  const capitalize = (word) => {
    const lower = word.toLowerCase();
    // Find index of first letter [a-z]
    const firstLetterIdx = lower.search(/[a-z]/);
    if (firstLetterIdx === -1) return word;

    return (
      lower.slice(0, firstLetterIdx) +
      lower[firstLetterIdx].toUpperCase() +
      lower.slice(firstLetterIdx + 1)
    );
  };

  const processWord = (word, isFirst, isLast) => {
    // Rule 1: Acronyms
    if (isAcronym(word)) return word;

    // Rule 2: Hyphenated words
    if (word.includes('-')) {
      return word
        .split('-')
        .map((part) => processWord(part, false, false))
        .join('-');
    }

    // Rule 4: Small words
    const lower = word.toLowerCase();
    if (smallWords.has(lower) && !isFirst && !isLast) {
      return lower;
    }

    // Rule 3: Capitalizing
    return capitalize(word);
  };

  // Split by whitespace but keep the whitespace structure
  // Using a regex with capturing group keeps the delimiters in the array
  const parts = text.split(/(\s+)/);
  const words = parts.filter((p) => !/^\s+$/.test(p) && p !== '');

  let wordIndex = 0;
  return parts
    .map((part) => {
      if (/^\s+$/.test(part) || part === '') {
        return part;
      }
      const isFirst = wordIndex === 0;
      const isLast = wordIndex === words.length - 1;
      const result = processWord(part, isFirst, isLast);
      wordIndex++;
      return result;
    })
    .join('');
}
