/**
 * Parses a duration string into milliseconds.
 * 
 * @param {string} input
 * @returns {number}
 * @throws {TypeError} If input is not a string.
 * @throws {RangeError} If input is invalid or malformed.
 */
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (trimmed === '') {
    throw new RangeError('Input cannot be empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000,
  };

  // Regex breakdown:
  // ^\s* : Start of string
  // (\d+(?:\.\d+)?) : Group 1: Number (digits, optional dot + digits)
  // ([a-z]+) : Group 2: Unit (letters)
  // \s* : Optional whitespace
  // Global flag to match all components
  const componentRegex = /(\d+(?:\.\d+)?)([a-z]+)/g;

  // Validate that the entire string is composed of valid components
  // We strip valid components and check if anything remains
  let matchCount = 0;
  let totalMs = 0;
  const seenUnits = new Set();

  // Check for invalid characters or structure by replacing valid parts
  const remainder = trimmed.replace(componentRegex, (_, num, unit) => {
    matchCount++;

    if (!units.hasOwnProperty(unit)) {
      throw new RangeError(`Invalid unit: ${unit}`);
    }
    if (seenUnits.has(unit)) {
      throw new RangeError(`Duplicate unit: ${unit}`);
    }

    seenUnits.add(unit);
    totalMs += parseFloat(num) * units[unit];
    return '';
  }).trim();

  if (remainder !== '' || matchCount === 0) {
    throw new RangeError('Invalid duration format');
  }

  return Math.round(totalMs);
}
