/**
 * Parses a single CSV line into an array of strings.
 * 
 * @param {string} line
 * @returns {string[]}
 * @throws {TypeError} If input is not a string.
 * @throws {RangeError} If the CSV format is invalid.
 */
export function parseCsvLine(line) {
  if (typeof line !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const fields = [];
  let i = 0;

  while (i <= line.length) {
    if (i < line.length && line[i] === '"') {
      // Quoted field
      let field = '';
      i++; // Skip opening quote
      let closed = false;

      while (i < line.length) {
        if (line[i] === '"') {
          if (i + 1 < line.length && line[i + 1] === '"') {
            // Escaped quote
            field += '"';
            i += 2;
          } else {
            // Closing quote
            closed = true;
            i++;
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }

      if (!closed) {
        throw new RangeError('Quoted field not closed');
      }

      // After a closing quote, we must see a comma or end of string
      if (i < line.length && line[i] !== ',') {
        throw new RangeError('Invalid character after closing quote');
      }

      fields.push(field);
      i++; // Skip comma
    } else {
      // Unquoted field
      let start = i;
      let end = line.indexOf(',', i);
      if (end === -1) end = line.length;

      const field = line.substring(start, end);

      // Check for illegal quotes in unquoted field
      if (field.includes('"')) {
        throw new RangeError('Quote found in unquoted field');
      }

      fields.push(field);
      i = end + 1; // Skip comma
    }

    // Handle trailing comma case: if line ends with comma, 
    // the loop continues and adds an empty string
    if (i === line.length + 1) {
      fields.push('');
      break;
    }
  }

  return fields;
}
