  result = result.replace(/[\s-]+/g, '_');

  // 3. Convert to lowercase
  result = result.toLowerCase();

  // 4. Collapse multiple underscores into one
  // Note: The requirement says "__init__" becomes "_init_".
  // This implies we only collapse internal runs, but keep leading/trailing if they existed.
  // However, the rule says "Runs of _ collapse... including at the start and end".
  // Let's normalize all runs of _ to a single _
  result = result.replace(/_+/g, '_');

  return result;
