/**
 * Roman numerals conversion module.
 */

const MAPPING = [
  [1000, 'M'],
  [900, 'CM'],
  [500, 'D'],
  [400, 'CD'],
  [100, 'C'],
  [90, 'XC'],
  [50, 'L'],
  [40, 'XL'],
  [10, 'X'],
  [9, 'IX'],
  [5, 'V'],
  [4, 'IV'],
  [1, 'I']
];

/**
 * Converts an integer from 1 to 3999 to its canonical Roman numeral.
 * @param {number} n
 * @returns {string}
 */
export function toRoman(n) {
  if (typeof n !== 'number') {
    throw new TypeError('Input must be a number.');
  }
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999.');
  }

  let result = '';
  let remaining = n;

  for (const [value, symbol] of MAPPING) {
    while (remaining >= value) {
      result += symbol;
      remaining -= value;
    }
  }

  return result;
}

/**
 * Converts a canonical Roman numeral string to an integer.
 * @param {string} text
 * @returns {number}
 */
export function fromRoman(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string.');
  }

  if (text.length === 0) {
    throw new RangeError('Input string is empty.');
  }

  // The strict requirement: fromRoman(toRoman(n)) must be n.
  // We can validate this by checking if the input matches the 
  // canonical form of the number it represents.

  let num = 0;
  let remaining = text;
  let i = 0;

  // Parse the string greedily to find the value
  for (const [value, symbol] of MAPPING) {
    while (remaining.startsWith(symbol)) {
      num += value;
      remaining = remaining.slice(symbol.length);
    }
  }

  // If there's anything left, or the string was invalid, 
  // or the generated canonical form doesn't match the input, it's invalid.
  if (remaining.length > 0 || num === 0 || toRoman(num) !== text) {
    throw new RangeError('Input is not a valid canonical Roman numeral.');
  }

  return num;
}
