  if (!vA.prerelease && !vB.prerelease) return 0;

  // 3. Compare individual identifiers
  const len = Math.max(vA.prerelease.length, vB.prerelease.length);
  for (let i = 0; i < len; i++) {
    const pA = vA.prerelease[i];
    const pB = vB.prerelease[i];

    if (pA === undefined) return -1;
    if (pB === undefined) return 1;

    const isNumA = /^\d+$/.test(pA);
    const isNumB = /^\d+$/.test(pB);

    if (isNumA && isNumB) {
      const nA = parseInt(pA, 10);
      const nB = parseInt(pB, 10);
      if (nA !== nB) return nA > nB ? 1 : -1;
    } else if (!isNumA && !isNumB) {
      if (pA !== pB) return pA > pB ? 1 : -1;
    } else {
