/**
 * Converts an identifier to snake_case.
 * 
 * @param {string} name
 * @returns {string}
 * @throws {TypeError}
 */
export function toSnakeCase(name) {
  if (typeof name !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (name === '') {
    return '';
  }

  // 1. Handle camelCase/PascalCase transitions:
  // Insert _ between lowercase/digit and uppercase: "aB" -> "a_B", "1B" -> "1_B"
  // Insert _ before the last capital in a sequence followed by lowercase: "XMLFile" -> "XML_File"
  let result = name
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2');

  // 2. Replace spaces, tabs, and hyphens with _
  result = result.replace(/[\s-]+/g, '_');

  // 3. Convert to lowercase
  result = result.toLowerCase();

  // 4. Collapse multiple underscores into one
  // Note: The requirement says __init__ becomes _init_. 
  // If we want to preserve leading/trailing underscores, we must be careful.
  // Rule 5: "Runs of _ collapse into a single _, including at the start and end."
  // This implies __init__ -> _init_
  result = result.replace(/_+/g, '_');

  return result;
}
