/**
 * A token-bucket rate limiter with an explicit clock.
 */
export class TokenBucket {
  #capacity;
  #refillPerSecond;
  #tokens;
  #lastMs;

  /**
   * @param {number} capacity - Maximum number of tokens.
   * @param {number} refillPerSecond - Tokens added per second.
   * @param {number} [startTimeMs=0] - Initial time.
   */
  constructor(capacity, refillPerSecond, startTimeMs = 0) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError("capacity must be a positive integer");
    }
    if (typeof refillPerSecond !== "number" || !Number.isFinite(refillPerSecond) || refillPerSecond <= 0) {
      throw new RangeError("refillPerSecond must be a positive, finite number");
    }
    if (typeof startTimeMs !== "number" || !Number.isFinite(startTimeMs)) {
      throw new RangeError("startTimeMs must be a finite number");
    }

    this.#capacity = capacity;
    this.#refillPerSecond = refillPerSecond;
    this.#tokens = capacity;
    this.#lastMs = startTimeMs;
  }

  /**
   * Updates the bucket state to the given time and returns current tokens.
   * @param {number} nowMs 
   * @returns {number}
   */
  #update(nowMs) {
    if (typeof nowMs !== "number" || !Number.isFinite(nowMs)) {
      throw new RangeError("nowMs must be a finite number");
    }

    if (nowMs > this.#lastMs) {
      const deltaSeconds = (nowMs - this.#lastMs) / 1000;
      const added = deltaSeconds * this.#refillPerSecond;
      this.#tokens = Math.min(this.#capacity, this.#tokens + added);
      this.#lastMs = nowMs;
    }
    return this.#tokens;
  }

  /**
   * Returns the number of tokens currently in the bucket.
   * @param {number} nowMs 
   * @returns {number}
   */
  available(nowMs) {
    return this.#update(nowMs);
  }

  /**
   * Attempts to take tokens from the bucket.
   * @param {number} count 
   * @param {number} nowMs 
   * @returns {boolean}
   */
  tryTake(count, nowMs) {
    if (!Number.isInteger(count) || count <= 0) {
      throw new RangeError("count must be a positive integer");
    }

    const currentTokens = this.#update(nowMs);

    if (count > this.#capacity) {
      return false;
    }

    if (currentTokens >= count) {
      this.#tokens -= count;
      return true;
    }

    return false;
  }
}
