/**
 * Converts text to title case according to specific rules.
 * @param {string} text
 * @returns {string}
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') {
    return '';
  }

  const smallWords = new Set([
    'a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as'
  ]);

  // Split by whitespace but keep the whitespace in the result
  const parts = text.split(/(\s+)/);

  const words = parts.map((part) => {
    if (/\s+/.test(part)) return part;
    return part;
  });

  // Identify indices of actual words (ignoring whitespace)
  const wordIndices = [];
  for (let i = 0; i < words.length; i++) {
    if (!/\s+/.test(words[i])) {
      wordIndices.push(i);
    }
  }

  const processWord = (word, isFirstOrLast) => {
    // Rule 1: Acronyms
    if (/^[A-Z]{2,}$/.test(word)) {
      return word;
    }

    // Rule 2: Hyphenated words
    if (word.includes('-')) {
      return word.split('-').map(part => processWord(part, false)).join('-');
    }

    // Rule 4: Small words
    const lower = word.toLowerCase();
    if (!isFirstOrLast && smallWords.has(lower)) {
      return lower;
    }

    // Rule 3: Capitalizing
    // Find index of first letter [a-zA-Z]
    const firstLetterIndex = word.search(/[a-zA-Z]/);
    if (firstLetterIndex === -1) return word;

    const prefix = word.slice(0, firstLetterIndex);
    const firstChar = word[firstLetterIndex].toUpperCase();
    const rest = word.slice(firstLetterIndex + 1).toLowerCase();
    return prefix + firstChar + rest;
  };

  wordIndices.forEach((idx, i) => {
    const isFirstOrLast = (i === 0 || i === wordIndices.length - 1);
    words[idx] = processWord(words[idx], isFirstOrLast);
  });

  return words.join('');
}
