 * 
 * @param {string} a
 * @param {string} b
 * @returns {-1 | 0 | 1}
 */
export function compareSemver(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') {
    throw new TypeError('Arguments must be strings');
  }

  const parse = (version) => {
    const regex = /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;
    const match = version.match(regex);
    if (!match) throw new RangeError('Invalid semantic version');

    const [_, major, minor, patch, prerelease] = match;
    return {
      version: [Number(major), Number(minor), Number(patch)],
      prerelease: prerelease ? prerelease.split('.') : null
    };
  };

  const vA = parse(a);
  const vB = parse(b);

  // 1. Compare MAJOR, MINOR, PATCH
  for (let i = 0; i < 3; i++) {
    if (vA.version[i] > vB.version[i]) return 1;
    if (vA.version[i] < vB.version[i]) return -1;
  }

  // 2. Compare Prerelease
  // A version with a prerelease is lower than the same version without one
  if (vA.prerelease && !vB.prerelease) return -1;
  if (!vA.prerelease && vB.prerelease) return 1;
  if (!vA.prerelease && !vB.prerelease) return 0;

  // 3. Compare identifiers
  const preA = vA.prerelease;
  const preB = vB.prerelease;
  const len = Math.max(preA.length, preB.length);

  for (let i = 0; i < len; i++) {
    if (i >= preA.length) return -1;
    if (i >= preB.length) return 1;

    const idA = preA[i];
    const idB = preB[i];

    const isNumA = /^\d+$/.test(idA);
    const isNumB = /^\d+$/.test(idB);

    if (isNumA && isNumB) {
      const numA = Number(idA);
      const numB = Number(idB);
      if (numA !== numB) return numA > numB ? 1 : -1;
    } else if (!isNumA && !isNumB) {
      if (idA !== idB) return idA > idB ? 1 : -1;
    } else {
      // Numeric is lower than alphanumeric
      return isNumA ? -1 : 1;
    }
  }

  return 0;
}
