/**
 * Parses a duration string into milliseconds.
 * 
 * @param {string} input
 * @returns {number}
 * @throws {TypeError} If input is not a string.
 * @throws {RangeError} If input format is invalid or units are repeated.
 */
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (trimmed === '') {
    throw new RangeError('Input is empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000,
  };

  // Regex breakdown:
  // ^\s* matches start
  // (\d+(?:\.\d+)?) matches number (must have digits before and after decimal if present)
  // ([a-z]+) matches unit
  // \s* matches separator
  // The global regex is used to iterate through components.
  const componentRegex = /(\d+(?:\.\d+)?)([a-z]+)/g;
  const foundUnits = new Set();
  let totalMs = 0;
  let lastIndex = 0;

  // Validate that the entire string is composed of valid components and whitespace
  // We use a regex that matches the whole string structure to ensure no invalid characters exist
  const fullMatchRegex = /^(\s*\d+(?:\.\d+)?[a-z]+\s*)+$/;
  if (!fullMatchRegex.test(trimmed)) {
    throw new RangeError('Invalid format');
  }

  let match;
  while ((match = componentRegex.exec(trimmed)) !== null) {
    const [_, valueStr, unit] = match;

    if (!units.hasOwnProperty(unit)) {
      throw new RangeError(`Invalid unit: ${unit}`);
    }
    if (foundUnits.has(unit)) {
      throw new RangeError(`Duplicate unit: ${unit}`);
    }

    foundUnits.add(unit);
    totalMs += parseFloat(valueStr) * units[unit];
  }

  return Math.round(totalMs);
}
