/**
 * Turns text into a URL-safe slug.
 * 
 * @param {string} text - The input text to slugify.
 * @param {Object} [options] - Configuration options.
 * @param {number} [options.maxLength] - Maximum length of the slug.
 * @returns {string} The slugified string.
 * @throws {TypeError} If text is not a string.
 * @throws {RangeError} If maxLength is provided but not a positive integer.
 */
export function slugify(text, options = {}) {
  if (typeof text !== 'string') {
    throw new TypeError('Input text must be a string.');
  }

  const { maxLength } = options;

  if (maxLength !== undefined) {
    if (!Number.isInteger(maxLength) || maxLength <= 0) {
      throw new RangeError('maxLength must be a positive integer.');
    }
  }

  // 1. Normalize Unicode NFKD and remove combining marks (U+0300-U+036F)
  let slug = text
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '');

  // 2. Lowercase
  slug = slug.toLowerCase();

  // 3. Replace non-alphanumeric characters with hyphens
  // 4. Remove leading/trailing hyphens
  slug = slug
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

  // 6. Handle maxLength
  if (maxLength !== undefined && slug.length > maxLength) {
    slug = slug.substring(0, maxLength);
    // Remove hyphens from the end again after cutting
    slug = slug.replace(/-+$/g, '');
  }

  return slug;
}
