/**
 * Roman numerals conversion module.
 */

const MAPPING = [
  [1000, 'M'],
  [900, 'CM'],
  [500, 'D'],
  [400, 'CD'],
  [100, 'C'],
  [90, 'XC'],
  [50, 'L'],
  [40, 'XL'],
  [10, 'X'],
  [9, 'IX'],
  [5, 'V'],
  [4, 'IV'],
  [1, 'I']
];

/**
 * Converts an integer from 1 to 3999 to its canonical Roman numeral.
 * @param {number} n
 * @returns {string}
 */
export function toRoman(n) {
  if (typeof n !== 'number') {
    throw new TypeError('Input must be a number.');
  }
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999.');
  }

  let result = '';
  let remaining = n;

  for (const [value, symbol] of MAPPING) {
    while (remaining >= value) {
      result += symbol;
      remaining -= value;
    }
  }

  return result;
}

/**
 * Converts a canonical Roman numeral string to an integer.
 * @param {string} text
 * @returns {number}
 */
export function fromRoman(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string.');
  }

  if (text.length === 0) {
    throw new RangeError('Input string is empty.');
  }

  // The strict requirement is that fromRoman(toRoman(n)) === n.
  // We can validate this by checking if the input matches the canonical form
  // of the number it represents.

  let value = 0;
  let remaining = text;
  let temp = 0;

  for (const [val, symbol] of MAPPING) {
    while (remaining.startsWith(symbol)) {
      temp += val;
      remaining = remaining.slice(symbol.length);
    }
  }

  // If there are leftover characters, it wasn't a valid canonical Roman numeral
  if (remaining.length > 0) {
    throw new RangeError('Invalid or non-canonical Roman numeral.');
  }

  // Verify that the reconstructed number produces the exact input string
  // This handles cases like "IIII" (which would parse to 4 but produce "IV")
  if (toRoman(temp) !== text) {
    throw new RangeError('Invalid or non-canonical Roman numeral.');
  }

  return temp;
}
