/**
 * Converts text to title case according to specific rules.
 * @param {string} text
 * @returns {string}
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') {
    return '';
  }

  const smallWords = new Set([
    'a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as'
  ]);

  // Split by whitespace but keep the whitespace structure
  // Using a regex with capturing group to keep delimiters
  const parts = text.split(/(\s+)/);

  const words = parts.map((part) => {
    if (/\s+/.test(part)) return part;
    return part;
  });

  // Identify indices of actual words
  const wordIndices = [];
  words.forEach((part, i) => {
    if (!/\s+/.test(part)) wordIndices.push(i);
  });

  const firstIdx = wordIndices[0];
  const lastIdx = wordIndices[wordIndices.length - 1];

  const processWord = (word, isFirst, isLast) => {
    // Rule 1: Acronyms
    if (/^[A-Z]{2,}$/.test(word)) {
      return word;
    }

    // Rule 2: Hyphenated words
    if (word.includes('-')) {
      return word.split('-').map(part => processWord(part, false, false)).join('-');
    }

    // Rule 4: Small words
    const lower = word.toLowerCase();
    if (smallWords.has(lower) && !isFirst && !isLast) {
      return lower;
    }

    // Rule 3: Capitalizing
    // Find the first letter index
    const firstLetterMatch = word.match(/[a-z]/i);
    if (!firstLetterMatch) return word;

    const idx = firstLetterMatch.index;
    return (
      word.slice(0, idx) +
      word[idx].toUpperCase() +
      word.slice(idx + 1).toLowerCase()
    );
  };

  wordIndices.forEach((idx) => {
    words[idx] = processWord(words[idx], idx === firstIdx, idx === lastIdx);
  });

  return words.join('');
}
