  if (text.length === 0) {
    throw new RangeError('Input cannot be empty.');
  }

  // Validate that the input is exactly the canonical form produced by toRoman
  // We can do this by checking if toRoman(fromRoman(text)) === text,
  // but we must first ensure the string is valid Roman syntax.

  // Regex for canonical Roman numerals:
  // M{0,3} (thousands)
  // (CM|CD|D?C{0,3}) (hundreds)
  // (XC|XL|L?X{0,3}) (tens)
  // (IX|IV|V?I{0,3}) (ones)
  const canonicalRegex = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;

