/**
 * An LRU (Least Recently Used) cache implementation.
 * Uses a Map to store entries. Since ES6 Maps maintain insertion order,
 * we can leverage this to track usage: re-inserting an entry moves it
 * to the "most recently used" position (the end of the Map).
 */
export class LruCache {
  #capacity;
  #cache;

  /**
   * @param {number} capacity
   */
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError("Capacity must be an integer of at least 1.");
    }
    this.#capacity = capacity;
    this.#cache = new Map();
  }

  /**
   * Returns the value, or undefined if the key is absent.
   * Updates the key to be the most recently used.
   * @param {*} key
   * @returns {*}
   */
  get(key) {
    if (!this.#cache.has(key)) {
      return undefined;
    }
    const value = this.#cache.get(key);
    // Refresh the key: delete and re-insert to move to the end (MRU)
    this.#cache.delete(key);
    this.#cache.set(key, value);
    return value;
  }

  /**
   * Stores the value and makes the key the most recently used.
   * @param {*} key
   * @param {*} value
   * @returns {LruCache}
   */
  set(key, value) {
    if (this.#cache.has(key)) {
      this.#cache.delete(key);
    } else if (this.#cache.size >= this.#capacity) {
      // Evict the least recently used (the first item in the Map)
      const firstKey = this.#cache.keys().next().value;
      this.#cache.delete(firstKey);
    }
    this.#cache.set(key, value);
    return this;
  }

  /**
   * Checks if the key exists without changing usage order.
   * @param {*} key
   * @returns {boolean}
   */
  has(key) {
    return this.#cache.has(key);
  }

  /**
   * Removes the key.
   * @param {*} key
   * @returns {boolean}
   */
  delete(key) {
    return this.#cache.delete(key);
  }

  /**
   * Returns the number of entries held.
   * @returns {number}
   */
  get size() {
    return this.#cache.size;
  }

  /**
   * Returns an array of keys from least to most recently used.
   * @returns {Array}
   */
  keys() {
    return Array.from(this.#cache.keys());
  }
}
