/**
 * Parses a single line of CSV into an array of strings.
 * 
 * @param {string} line
 * @returns {string[]}
 * @throws {TypeError} if input is not a string
 * @throws {RangeError} if the CSV format is invalid
 */
export function parseCsvLine(line) {
  if (typeof line !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const result = [];
  let i = 0;

  while (i <= line.length) {
    if (i < line.length && line[i] === '"') {
      // Quoted field
      let field = '';
      i++; // Skip opening quote
      let closed = false;

      while (i < line.length) {
        if (line[i] === '"') {
          if (i + 1 < line.length && line[i + 1] === '"') {
            // Escaped quote
            field += '"';
            i += 2;
          } else {
            // Closing quote
            closed = true;
            i++;
            break;
          }
        } else {
          field += line[i];
          i++;
        }
      }

      if (!closed) {
        throw new RangeError('Unclosed quoted field');
      }

      // After a closing quote, we must see a comma or end of string
      if (i < line.length && line[i] !== ',') {
        throw new RangeError('Invalid character after closing quote');
      }

      result.push(field);
      i++; // Skip comma
    } else {
      // Unquoted field
      let field = '';
      while (i < line.length && line[i] !== ',') {
        if (line[i] === '"') {
          throw new RangeError('Quote found inside unquoted field');
        }
        field += line[i];
        i++;
      }
      result.push(field);
      i++; // Skip comma
    }

    // Handle trailing comma case: if line ends with ',', 
    // the loop condition i <= line.length ensures we process the empty field.
    if (i > line.length) break;
  }

  return result;
}
