 * 
 * @param {string} name
 * @returns {string}
 * @throws {TypeError}
 */
export function toSnakeCase(name) {
  if (typeof name !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (name === '') {
    return '';
  }

  // 1 & 2: Handle camelCase and PascalCase boundaries.
  // - Insert underscore between lowercase/digit and uppercase: (a|d)(A) -> $1_$2
  // - Insert underscore before the last capital in a run of capitals followed by lowercase: (A)(A)(a) -> $1_$2$3
  let result = name
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2');

  // 3: Replace spaces, tabs, hyphens, and existing underscores with a single underscore.
  // We use a regex that captures all these separators.
  result = result.replace(/[\s\-\_]+/g, '_');

  // 4: Lowercase the entire string.
  result = result.toLowerCase();

  // 5: Handle leading/trailing underscores.
  // The logic above might leave leading/trailing underscores if the input had them.
  // The requirement says: "__init__" becomes "_init_".
  // Our regex replacement already handles collapsing multiple underscores.
  // We just need to ensure we don't strip the ones that are part of the identifier structure
  // if they were intended (like leading underscores in private variables).

  return result;
}
