/**
 * Compares two semantic version strings.
 * 
 * @param {string} a
 * @param {string} b
 * @returns {-1 | 0 | 1}
 */
export function compareSemver(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') {
    throw new TypeError('Arguments must be strings');
  }

  const parse = (v) => {
    const regex = /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$/;
    const match = v.match(regex);
    if (!match) throw new RangeError('Invalid semantic version');

    const [_, major, minor, patch, prerelease] = match;
    return {
      version: [Number(major), Number(minor), Number(patch)],
      prerelease: prerelease ? prerelease.split('.') : null
    };
  };

  const vA = parse(a);
  const vB = parse(b);

  // 1. Compare MAJOR, MINOR, PATCH
  for (let i = 0; i < 3; i++) {
    if (vA.version[i] > vB.version[i]) return 1;
    if (vA.version[i] < vB.version[i]) return -1;
  }

  // 2. Prerelease existence
  if (vA.prerelease && !vB.prerelease) return -1;
  if (!vA.prerelease && vB.prerelease) return 1;
  if (!vA.prerelease && !vB.prerelease) return 0;

  // 3. Compare prereleases
  const len = Math.max(vA.prerelease.length, vB.prerelease.length);
  for (let i = 0; i < len; i++) {
    const pA = vA.prerelease[i];
    const pB = vB.prerelease[i];

    if (pA === undefined) return -1;
    if (pB === undefined) return 1;

    const isNumA = /^\d+$/.test(pA);
    const isNumB = /^\d+$/.test(pB);

    if (isNumA && isNumB) {
      const nA = Number(pA);
      const nB = Number(pB);
      if (nA !== nB) return nA > nB ? 1 : -1;
    } else if (isNumA || isNumB) {
      return isNumA ? -1 : 1;
    } else {
      if (pA !== pB) return pA > pB ? 1 : -1;
    }
  }

  return 0;
}
