 * @param {string} text
 * @returns {string}
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') return '';

  const smallWords = new Set([
    'a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as'
  ]);

  const isAcronym = (word) => /^[A-Z]{2,}$/.test(word);

  const capitalizeWord = (word) => {
    if (isAcronym(word)) return word;

    const lower = word.toLowerCase();
    let result = '';
    let foundFirstLetter = false;

    for (let i = 0; i < lower.length; i++) {
      const char = lower[i];
      if (!foundFirstLetter && /[a-z]/.test(char)) {
        result += char.toUpperCase();
        foundFirstLetter = true;
      } else {
        result += char;
      }
    }
    return result;
  };

  const processWord = (word, isFirst, isLast) => {
    if (word.includes('-')) {
      return word
        .split('-')
        .map((part) => (isAcronym(part) ? part : capitalizeWord(part)))
        .join('-');
    }

    const lower = word.toLowerCase();
    if (smallWords.has(lower) && !isFirst && !isLast) {
      return lower;
    }

    return capitalizeWord(word);
  };

  // Split by whitespace but keep the whitespace structure
  // We use a regex that captures whitespace to reconstruct the string later
  const parts = text.split(/(\s+)/);
  const words = parts.filter((p) => !/^\s+$/.test(p) && p !== '');

  let wordIndex = 0;
  const result = parts.map((part) => {
    if (/^\s+$/.test(part) || part === '') {
      return part;
    }
    const isFirst = wordIndex === 0;
    const isLast = wordIndex === words.length - 1;
    const processed = processWord(part, isFirst, isLast);
    wordIndex++;
    return processed;
  });

  return result.join('');
}
