/**
 * Converts text to title case according to specific rules.
 * @param {string} text
 * @returns {string}
 */
export function titleCase(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string');
  }

  if (text === '') return '';

  const smallWords = new Set([
    'a', 'an', 'the', 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'of', 'in', 'on', 'at', 'to', 'by', 'up', 'as'
  ]);

  const isAcronym = (word) => /^[A-Z]{2,}$/.test(word);

  const capitalize = (word) => {
    const match = word.match(/^[^a-zA-Z]*([a-zA-Z])(.*)$/);
    if (!match) return word;
    const prefix = word.slice(0, match.index + match[1].length - 1);
    const firstLetter = match[1].toUpperCase();
    const rest = match[2].toLowerCase();
    return prefix + firstLetter + rest;
  };

  const processWord = (word, isFirst, isLast) => {
    // Rule 1: Acronyms
    if (isAcronym(word)) return word;

    // Rule 2: Hyphenated words
    if (word.includes('-')) {
      return word.split('-').map(part => processWord(part, false, false)).join('-');
    }

    // Rule 4: Small words
    const lower = word.toLowerCase();
    if (smallWords.has(lower) && !isFirst && !isLast) {
      return lower;
    }

    // Rule 3: Capitalizing
    return capitalize(word);
  };

  // Split by whitespace but keep the whitespace structure
  // Using a regex with capturing group to keep delimiters
  const parts = text.split(/(\s+)/);
  const words = parts.filter(p => !/^\s+$/.test(p) && p !== '');

  if (words.length === 0) return text;

  const firstWord = words[0];
  const lastWord = words[words.length - 1];

  let wordIndex = 0;
  return parts.map(part => {
    if (/^\s+$/.test(part) || part === '') {
      return part;
    }
    const isFirst = (part === firstWord && wordIndex === 0);
    const isLast = (part === lastWord && wordIndex === words.length - 1);
    wordIndex++;
    return processWord(part, isFirst, isLast);
  }).join('');
}
