/**
 * Merges overlapping intervals.
 * 
 * @param {Array<[number, number]>} intervals
 * @returns {Array<[number, number]>}
 */
export function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError("Input must be an array.");
  }

  if (intervals.length === 0) {
    return [];
  }

  // Validate input structure and values
  const validated = intervals.map((interval) => {
    if (!Array.isArray(interval) || interval.length !== 2) {
      throw new TypeError("Each interval must be an array of two numbers.");
    }

    const [start, end] = interval;

    if (typeof start !== 'number' || typeof end !== 'number' || 
        !Number.isFinite(start) || !Number.isFinite(end)) {
      throw new RangeError("Interval values must be finite numbers.");
    }

    if (start > end) {
      throw new RangeError("Start must be less than or equal to end.");
    }

    return [start, end];
  });

  // Sort by start time (create a shallow copy to avoid mutating original)
  const sorted = [...validated].sort((a, b) => a[0] - b[0]);

  const result = [];
  if (sorted.length > 0) {
    let current = [...sorted[0]];

    for (let i = 1; i < sorted.length; i++) {
      const next = sorted[i];

      // If next interval starts before or exactly when current ends, merge
      if (next[0] <= current[1]) {
        current[1] = Math.max(current[1], next[1]);
      } else {
        // Push the completed interval and move to the next
        result.push(current);
        current = [...next];
      }
    }
    result.push(current);
  }

  return result;
}
