/**
 * Wraps text into lines of at most `width` characters.
 * 
 * @param {string} text 
 * @param {number} width 
 * @returns {string[]}
 */
export function wrapText(text, width) {
  if (typeof text !== 'string') {
    throw new TypeError('Text must be a string.');
  }
  if (!Number.isInteger(width) || width < 1) {
    throw new RangeError('Width must be an integer of at least 1.');
  }

  const words = text.split(/\s+/).filter(w => w.length > 0);
  if (words.length === 0) {
    return [];
  }

  const lines = [];
  let currentLine = [];
  let currentLength = 0;

  for (const word of words) {
    // If the word itself is longer than width, break it into pieces
    if (word.length > width) {
      // 1. Finish current line if it exists
      if (currentLine.length > 0) {
        lines.push(currentLine.join(' '));
        currentLine = [];
        currentLength = 0;
      }

      // 2. Break the long word into chunks of `width`
      for (let i = 0; i < word.length; i += width) {
        const chunk = word.slice(i, i + width);
        if (chunk.length === width) {
          lines.push(chunk);
        } else {
          // Last piece becomes the start of the next line
          currentLine = [chunk];
          currentLength = chunk.length;
        }
      }
    } else {
      // Normal word fitting logic
      // Check if word fits: current + space + word
      const needed = currentLine.length === 0 ? word.length : currentLength + 1 + word.length;

      if (needed <= width) {
        currentLine.push(word);
        currentLength = needed;
      } else {
        // Push current line and start new one
        lines.push(currentLine.join(' '));
        currentLine = [word];
        currentLength = word.length;
      }
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine.join(' '));
  }

  return lines;
}
