/**
 * Parses a duration string into milliseconds.
 * 
 * @param {string} input
 * @returns {number}
 * @throws {TypeError} If input is not a string.
 * @throws {RangeError} If input format is invalid or units are repeated.
 */
export function parseDuration(input) {
  if (typeof input !== 'string') {
    throw new TypeError('Input must be a string');
  }

  const trimmed = input.trim();
  if (trimmed === '') {
    throw new RangeError('Input is empty');
  }

  const units = {
    ms: 1,
    s: 1000,
    m: 60 * 1000,
    h: 60 * 60 * 1000,
    d: 24 * 60 * 60 * 1000,
    w: 7 * 24 * 60 * 60 * 1000,
  };

  // Regex breakdown:
  // ^\s* matches start
  // (\d+(?:\.\d+)?) matches number (no leading/trailing dots)
  // ([a-z]+) matches unit
  // \s* matches potential whitespace between components
  const componentRegex = /^(\d+(?:\.\d+)?)([a-z]+)$/;
  const parts = trimmed.split(/\s+/);
  const seenUnits = new Set();
  let totalMs = 0;

  for (const part of parts) {
    const match = part.match(componentRegex);

    if (!match) {
      throw new RangeError(`Invalid component format: ${part}`);
    }

    const [, valueStr, unit] = match;

    if (!units.hasOwnProperty(unit)) {
      throw new RangeError(`Unknown unit: ${unit}`);
    }

    if (seenUnits.has(unit)) {
      throw new RangeError(`Duplicate unit: ${unit}`);
    }

    seenUnits.add(unit);
    totalMs += parseFloat(valueStr) * units[unit];
  }

  return Math.round(totalMs);
}
