/**
 * Roman numerals conversion module.
 */

const MAPPING = [
  [1000, 'M'],
  [900, 'CM'],
  [500, 'D'],
  [400, 'CD'],
  [100, 'C'],
  [90, 'XC'],
  [50, 'L'],
  [40, 'XL'],
  [10, 'X'],
  [9, 'IX'],
  [5, 'V'],
  [4, 'IV'],
  [1, 'I']
];

/**
 * Converts an integer from 1 to 3999 to its canonical Roman numeral.
 * @param {number} n
 * @returns {string}
 */
export function toRoman(n) {
  if (typeof n !== 'number') {
    throw new TypeError('Input must be a number.');
  }
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Input must be an integer between 1 and 3999.');
  }

  let result = '';
  let remaining = n;

  for (const [value, symbol] of MAPPING) {
    while (remaining >= value) {
      result += symbol;
      remaining -= value;
    }
  }

  return result;
}

/**
 * Converts a canonical Roman numeral string to an integer.
 * @param {string} text
 * @returns {number}
 */
export function fromRoman(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Input must be a string.');
  }

  if (text.length === 0) {
    throw new RangeError('Input cannot be empty.');
  }

  // The requirement is that fromRoman(toRoman(n)) === n.
  // We can validate this by generating the canonical form for the 
  // potential number and comparing it to the input.

  // Regex to ensure valid characters and structure (optional but good for performance)
  // A strict regex for canonical Roman numerals:
  const canonicalRegex = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;
  if (!canonicalRegex.test(text)) {
    throw new RangeError('Invalid canonical Roman numeral.');
  }

  // Calculate value
  let result = 0;
  let remaining = text;

  for (const [value, symbol] of MAPPING) {
    while (remaining.startsWith(symbol)) {
      result += value;
      remaining = remaining.slice(symbol.length);
    }
  }

  // Final check: if the input was not fully consumed or result is 0, it's invalid
  if (remaining.length > 0 || result === 0) {
    throw new RangeError('Invalid canonical Roman numeral.');
  }

  // Ensure the input is exactly the canonical form
  if (toRoman(result) !== text) {
    throw new RangeError('Input is not a canonical Roman numeral.');
  }

  return result;
}
