  }

  if (!Number.isInteger(decimals) || decimals < 0 || decimals > 3) {
    throw new RangeError('Decimals must be an integer between 0 and 3.');
  }

  const base = binary ? 1024 : 1000;
  const units = binary
    ? ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB']
    : ['B', 'kB', 'MB', 'GB', 'TB', 'PB'];

  // Round to nearest integer for the base case
  let roundedBytes = Math.round(bytes);

  if (roundedBytes < base) {
    return `${roundedBytes} B`;
  }

  let unitIndex = 0;
  let value = bytes;

  // Find the appropriate unit
  while (value >= base && unitIndex < units.length - 1) {
    value /= base;
    unitIndex++;
  }

  // Round to the specified decimals
  const factor = Math.pow(10, decimals);
  value = Math.round(value * factor) / factor;

  // Handle the case where rounding pushes the value to the base
  if (value >= base && unitIndex < units.length - 1) {
    value /= base;
    unitIndex++;
  }

  return `${value.toFixed(decimals)} ${units[unitIndex]}`;
